def _boss_open_ids(cfg: dict[str, Any]) -> list[str]:
    notify = cfg.get("notify") or {}
    raw = notify.get("boss_open_ids")
    if isinstance(raw, str) and raw.strip():
        return [raw.strip()]
    if isinstance(raw, list):
        return [str(x).strip() for x in raw if x]
