from __future__ import annotations

import logging
import time
from typing import Any, Iterator

import httpx

from app.config import Settings, get_settings

logger = logging.getLogger(__name__)


class FeishuError(Exception):
    def __init__(self, code: int | str, message: str, payload: Any = None) -> None:
        super().__init__(f"[{code}] {message}")
        self.code = code
        self.message = message
        self.payload = payload


class FeishuClient:
    """飞书开放平台：tenant token + 多维表格 + 自定义机器人 webhook。"""

    BASE = "https://open.feishu.cn/open-apis"

    def __init__(self, settings: Settings | None = None, timeout: float = 60.0) -> None:
        self.settings = settings or get_settings()
        if not self.settings.has_feishu:
            raise FeishuError("config", "缺少 FEISHU_APP_ID / FEISHU_APP_SECRET")
        self._http = httpx.Client(timeout=timeout)
        self._token: str | None = None
        self._token_expire_at: float = 0.0

    def close(self) -> None:
        self._http.close()

    def __enter__(self) -> FeishuClient:
        return self

    def __exit__(self, *args: object) -> None:
        self.close()

    def get_tenant_access_token(self, *, force: bool = False) -> str:
        if not force and self._token and self._token_expire_at - 60 > time.time():
            return self._token
        url = f"{self.BASE}/auth/v3/tenant_access_token/internal"
        resp = self._http.post(
            url,
            json={
                "app_id": self.settings.feishu_app_id,
                "app_secret": self.settings.feishu_app_secret,
            },
        )
        resp.raise_for_status()
        data = resp.json()
        if data.get("code") != 0:
            raise FeishuError(data.get("code"), data.get("msg") or "token failed", data)
        self._token = data["tenant_access_token"]
        self._token_expire_at = time.time() + int(data.get("expire") or 7200)
        return self._token

    def _headers(self) -> dict[str, str]:
        return {
            "Authorization": f"Bearer {self.get_tenant_access_token()}",
            "Content-Type": "application/json; charset=utf-8",
        }

    def _api(
        self,
        method: str,
        path: str,
        *,
        params: dict[str, Any] | None = None,
        json_body: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        url = f"{self.BASE}{path}"
        resp = self._http.request(
            method,
            url,
            headers=self._headers(),
            params=params,
            json=json_body,
        )
        try:
            data = resp.json()
        except Exception:
            resp.raise_for_status()
            raise FeishuError(resp.status_code, resp.text[:500])
        # 飞书业务错误常伴随 HTTP 400，优先解析 body
        if data.get("code") not in (0, None) or not resp.is_success:
            if data.get("code") in (0, None) and not resp.is_success:
                raise FeishuError(resp.status_code, resp.text[:500], data)
            if data.get("code") not in (0, None):
                raise FeishuError(
                    data.get("code"),
                    data.get("msg") or "api error",
                    data,
                )
        return data

    # --- bitable meta ---
    def create_bitable_app(self, name: str, *, folder_token: str | None = None) -> dict[str, Any]:
        """创建多维表格应用，返回 app 信息（含 app_token）。"""
        body: dict[str, Any] = {"name": name}
        if folder_token:
            body["folder_token"] = folder_token
        data = self._api("POST", "/bitable/v1/apps", json_body=body)
        return data.get("data") or {}

    def list_tables(self, app_token: str) -> list[dict[str, Any]]:
        data = self._api("GET", f"/bitable/v1/apps/{app_token}/tables")
        items = (data.get("data") or {}).get("items") or []
        return items

    def create_table(
        self,
        app_token: str,
        name: str,
        fields: list[dict[str, Any]],

        to_fields=to_fields,
        shop_key="shop_name",
        mode="upsert",
    )
    return int(stats.get("mother") or 0)


# 负责人在飞书写入的运营动作列：系统日批 upsert 一律不碰，避免冲掉人工填写。
# 注意：「执行日期」由系统根据「采取动作」自动回填，不在此集合；见 fill_exec_date_from_action。
HUMAN_ACTION_FIELD_NAMES = frozenset(
    {
        "是否属实",
        "原因",
        "判断依据",
        "采取动作",
        "执行人",
        "需审核事项",
        "复查日期",
        "动作前数据",
        "动作后数据",
        "是否有效",
        "下一步动作",
        "闭环状态",
    }
)

ACTION_FIELD = "采取动作"
EXEC_DATE_FIELD = "执行日期"


def _field_nonempty(v: Any) -> bool:
    if v is None:
        return False
    if isinstance(v, str):
        return bool(v.strip())
    if isinstance(v, (list, dict)):
        return len(v) > 0
    return True


def _exec_date_value_for_table(
    *,
    field_type: int | None,
    when_ms: int,
    when_day: str,
) -> Any:
    """DATE 字段写毫秒；文本日期写 YYYY-MM-DD。"""
    if field_type == 5:
        return when_ms
    return when_day


def fill_exec_date_from_action(
    *,
    settings: Settings | None = None,
    dry_run: bool = False,
) -> dict[str, int]:
    """扫描异常任务（母表+子表）：有「采取动作」且「执行日期」为空时，系统写入当天日期。

    语义：执行日期 = 系统首次检测到「采取动作」已填写的业务日（近似填写日）。
    已有执行日期的不覆盖；清空采取动作也不会清执行日期。
    """
    from datetime import datetime, timezone

    from app.clients.feishu import FeishuClient

    settings = settings or get_settings()
    stats = {
        "tables": 0,
        "scanned": 0,
        "filled": 0,
        "skipped_has_date": 0,
        "skipped_no_action": 0,
        "errors": 0,
    }
    if not settings.has_feishu or not settings.feishu_bitable_app_token:
        logger.warning("飞书未配置，跳过执行日期回填")
        return stats
    mother = settings.feishu_table_tasks
    if not mother:
        return stats

    targets: list[tuple[str, str]] = [("母表", mother)]
    if dual_write_enabled():
        try:
            reg = ShopTableRegistry.load(settings.shop_tables_path)
            for shop, tid in reg.all_table_ids("tasks"):
                targets.append((f"子表-{shop}", tid))
        except Exception:
            logger.exception("加载子表注册表失败，仅处理母表")

    now = datetime.now(timezone.utc)
    when_day = now.strftime("%Y-%m-%d")
    when_ms = int(
        datetime(now.year, now.month, now.day, tzinfo=timezone.utc).timestamp() * 1000
    )

    app = settings.feishu_bitable_app_token
    with FeishuClient(settings) as client:
        for label, table_id in targets:
            stats["tables"] += 1
            try:
                ftypes = {
                    f.get("field_name"): f.get("type")
                    for f in client.list_fields(app, table_id)
                }
                if ACTION_FIELD not in ftypes or EXEC_DATE_FIELD not in ftypes:
                    logger.warning(
                        "[%s] 缺少字段 %s/%s，跳过",
                        label,
                        ACTION_FIELD,
                        EXEC_DATE_FIELD,
                    )
                    continue
                exec_type = ftypes.get(EXEC_DATE_FIELD)
                updates: list[dict[str, Any]] = []
                for item in client.iter_records(app, table_id, page_size=100):
                    stats["scanned"] += 1
                    fields = item.get("fields") or {}
                    rid = item.get("record_id")
                    if not rid:
                        continue
                    action = fields.get(ACTION_FIELD)
                    exec_date = fields.get(EXEC_DATE_FIELD)
                    if not _field_nonempty(action):
                        stats["skipped_no_action"] += 1
                        continue
                    if _field_nonempty(exec_date):
                        stats["skipped_has_date"] += 1
                        continue
                    val = _exec_date_value_for_table(
                        field_type=int(exec_type) if exec_type is not None else None,
                        when_ms=when_ms,
                        when_day=when_day,
                    )
                    updates.append(
                        {"record_id": rid, "fields": {EXEC_DATE_FIELD: val}}
                    )
                if dry_run:
                    stats["filled"] += len(updates)
                    logger.info(
                        "[DRY-RUN][%s] 将回填执行日期 %s 条", label, len(updates)
                    )
                    continue
                for i in range(0, len(updates), 100):
                    chunk = updates[i : i + 100]
                    if chunk:
                        client.bitable_batch_update(app, table_id, chunk)
                        stats["filled"] += len(chunk)
                        time.sleep(0.2)
                logger.info("[%s] 执行日期回填 %s 条", label, len(updates))
            except Exception:
                stats["errors"] += 1
                logger.exception("[%s] 执行日期回填失败", label)

    logger.info("fill_exec_date_from_action: %s", stats)
    return stats


def write_tasks_to_feishu(
    tasks: list[dict[str, Any]],
    *,
    settings: Settings | None = None,
) -> int:
    settings = settings or get_settings()
    table_id = settings.feishu_table_tasks
    if not settings.has_feishu or not settings.feishu_bitable_app_token or not table_id:
        logger.warning("飞书任务表未配置，跳过任务同步")
        return 0

    def to_fields(t: dict[str, Any]) -> dict[str, Any] | None:
        fields = task_to_fields(t)
        fields = {k: v for k, v in fields.items() if v is not None}
        # 合并表后：动作列只给人填，系统同步只更新异常/责任字段
        for name in HUMAN_ACTION_FIELD_NAMES:
            fields.pop(name, None)
        if not fields.get("主键"):
            return None
        return fields

def list_tables(self, app_token: str) -> list[dict[str, Any]]:
    data = self._api("GET", f"/bitable/v1/apps/{app_token}/tables")
    items = (data.get("data") or {}).get("items") or []
    return items

def create_table(
    self,
    app_token: str,
    name: str,
    fields: list[dict[str, Any]],
) -> dict[str, Any]:
    """fields 例: [{"field_name":"日期","type":5}, ...]  type 见飞书文档。"""
    body = {"table": {"name": name, "default_view_name": "默认视图", "fields": fields}}
    data = self._api(
        "POST",
        f"/bitable/v1/apps/{app_token}/tables",
        json_body=body,
    )
    return data.get("data") or {}

def list_fields(self, app_token: str, table_id: str) -> list[dict[str, Any]]:
    data = self._api(
        "GET",
        f"/bitable/v1/apps/{app_token}/tables/{table_id}/fields",
    )
    return (data.get("data") or {}).get("items") or []

def create_field(
    self,
    app_token: str,
    table_id: str,
    field_name: str,
    field_type: int,
    *,
    property_: dict[str, Any] | None = None,
) -> dict[str, Any]:
    body: dict[str, Any] = {"field_name": field_name, "type": field_type}
    if property_:
        body["property"] = property_
    data = self._api(
        "POST",
        f"/bitable/v1/apps/{app_token}/tables/{table_id}/fields",
        json_body=body,
    )
    return data.get("data") or {}

# --- views ---
def list_views(self, app_token: str, table_id: str) -> list[dict[str, Any]]:
    data = self._api("GET", f"/bitable/v1/apps/{app_token}/tables/{table_id}/views")
    return (data.get("data") or {}).get("items") or []

def create_view(
    self,
    app_token: str,
    table_id: str,
    view_name: str,
    *,
    view_type: str = "grid",
) -> dict[str, Any]:
    data = self._api(
        "POST",
        f"/bitable/v1/apps/{app_token}/tables/{table_id}/views",
        json_body={"view_name": view_name, "view_type": view_type},
    )
    return (data.get("data") or {}).get("view") or data.get("data") or {}

def patch_view(
    self,
    app_token: str,
    table_id: str,
    view_id: str,
    body: dict[str, Any],
) -> dict[str, Any]:
    data = self._api(
        "PATCH",
        f"/bitable/v1/apps/{app_token}/tables/{table_id}/views/{view_id}",
        json_body=body,
    )
    return data.get("data") or {}

def delete_view(self, app_token: str, table_id: str, view_id: str) -> None:
    """删除视图。"""
    self._api(
        "DELETE",
        f"/bitable/v1/apps/{app_token}/tables/{table_id}/views/{view_id}",
    )

def patch_view_filter(
    self,
    app_token: str,
    table_id: str,
    view_id: str,
    *,
    field_id: str,
    operator: str,
    value: str,
    conjunction: str = "and",
) -> dict[str, Any]:
    """设置单条件筛选。value 格式因字段类型而异，常见为 JSON 数组字符串如 '["特米-UK"]'。"""
    body = {
        "property": {
            "filter_info": {
                "conjunction": conjunction,
                "conditions": [
                    {
                        "field_id": field_id,
                        "operator": operator,
                        "value": value,
                    }
                ],
            }
        }
    }
    return self.patch_view(app_token, table_id, view_id, body)

def patch_view_filter_or(
    self,
    app_token: str,
    table_id: str,
    view_id: str,
    *,
    field_id: str,
    values: list[str],
    operator: str = "is",
) -> dict[str, Any]:
    """多值 OR 筛选：店铺 is A OR is B OR is C。"""
    import json

    conditions = []
    for v in values:
        if not v:
            continue
        conditions.append(
            {
                "field_id": field_id,
                "operator": operator,
                "value": json.dumps([v], ensure_ascii=False),
            }
        )
    if not conditions:
        raise FeishuError("filter", "patch_view_filter_or 需要至少一个 value")
    body = {
        "property": {
            "filter_info": {
                "conjunction": "or" if len(conditions) > 1 else "and",
                "conditions": conditions,
            }
        }
    }
    return self.patch_view(app_token, table_id, view_id, body)

def field_id_map(self, app_token: str, table_id: str) -> dict[str, str]:
    return {
        f.get("field_name"): f.get("field_id")
        for f in self.list_fields(app_token, table_id)
        if f.get("field_name") and f.get("field_id")
    }

# --- records ---
def bitable_list_records(
    self,
    app_token: str,
    table_id: str,
    *,
    page_size: int = 100,
    page_token: str | None = None,
    filter_expr: str | None = None,
) -> dict[str, Any]:
    params: dict[str, Any] = {"page_size": page_size}
    if page_token:
        params["page_token"] = page_token
    if filter_expr:
        params["filter"] = filter_expr
    data = self._api(
        "GET",
        f"/bitable/v1/apps/{app_token}/tables/{table_id}/records",
        params=params,
    )
    return data.get("data") or {}

def iter_records(
    self,
    app_token: str,
    table_id: str,
    *,
    page_size: int = 100,
    filter_expr: str | None = None,
) -> Iterator[dict[str, Any]]:
    page_token = None
    while True:
        data = self.bitable_list_records(
            app_token,
            table_id,
            page_size=page_size,
            page_token=page_token,
            filter_expr=filter_expr,
        )
        for item in data.get("items") or []:
            yield item

