"""Probe Feishu field_perm API for locking 执行日期."""
from __future__ import annotations

import json

from app.clients.feishu import FeishuClient
from app.config import get_settings


def main() -> None:
    s = get_settings()
    app = s.feishu_bitable_app_token
    with FeishuClient(s) as c:
        data = c._api("GET", f"/bitable/v1/apps/{app}/roles")
        items = (data.get("data") or {}).get("items") or []
        for r in items:
            print("ROLE", r.get("role_id"), r.get("role_name"))
            for tr in r.get("table_roles") or []:
                name = str(tr.get("table_name") or "")
                if "异常任务" in name or tr.get("field_perm"):
                    print(
                        "  table",
                        name,
                        "perm",
                        tr.get("table_perm"),
                        "fp_count",
                        len(tr.get("field_perm") or {}),
                        "sample",
                        list((tr.get("field_perm") or {}).items())[:3],
                    )

        tables = c.list_tables(app)
        task_tables = [
            t for t in tables if str(t.get("name") or "").startswith("异常任务")
        ]
        print(
            "task_tables",
            [(t.get("name"), t.get("table_id")) for t in task_tables],
        )

        mother = s.feishu_table_tasks
        fields = c.list_fields(app, mother)
        fmap = {
            f["field_name"]: f["field_id"]
            for f in fields
            if f.get("field_name") and f.get("field_id")
        }
        exec_fid = fmap["执行日期"]
        print("exec_fid", exec_fid, "fields", len(fmap))

        trials = [
            ("only_exec_2", {exec_fid: 2}),
            ("all_1_exec_2", {**{fid: 1 for fid in fmap.values()}, exec_fid: 2}),
            ("all_edit_exec_ro_str", {**{fid: "1" for fid in fmap.values()}, exec_fid: "2"}),
            (
                "with_rec_rule",
                {**{fid: 1 for fid in fmap.values()}, exec_fid: 2},
            ),
        ]
        for label, fp in trials:
            body: dict = {
                "role_name": f"测试_{label}",
                "table_roles": [
                    {
                        "table_id": mother,
                        "table_perm": 2,
                        "allow_add_record": True,
                        "allow_delete_record": False,
                        "field_perm": fp,
                    }
                ],
            }
            if label == "with_rec_rule":
                # non-empty condition sometimes required; use ASIN is not empty if possible
                asin_fid = fmap.get("ASIN")
                if asin_fid:
                    body["table_roles"][0]["rec_rule"] = {
                        "conjunction": "and",
                        "conditions": [
                            {
                                "field_id": asin_fid,
                                "operator": "isNotEmpty",
                                "value": [],
                            }
                        ],
                        "other_perm": 1,
                    }
            try:
                data = c._api("POST", f"/bitable/v1/apps/{app}/roles", json_body=body)
                role = (data.get("data") or {}).get("role") or {}
                tr = (role.get("table_roles") or [{}])[0]
                print(
                    "OK",
                    label,
                    "table_perm",
                    tr.get("table_perm"),
                    "field_perm",
                    tr.get("field_perm"),
                )
                rid = role.get("role_id")
                if rid:
                    try:
                        c._api("DELETE", f"/bitable/v1/apps/{app}/roles/{rid}")
                        print(" deleted", rid)
                    except Exception as e:
                        print(" del err", e)
            except Exception as e:
                print("ERR", label, e)


if __name__ == "__main__":
    main()

